export default function cases(): GoldenCase[] {
  const out: GoldenCase[] = [];
  out.push(gc('constants', [], { NOTE_MAX_LENGTH }));
  for (const t of texts) {
    out.push(gc('extractAmount', [t], extractAmount(t)));
    out.push(gc('inferTransactionType', [t], inferTransactionType(t)));
  }

  const payloads: Record<string, string | null | undefined>[] = [
    {},
    { title: 'Swiggy', text: 'Rs 99 debited' },
    { text: 'Rs 1,234.50 debited' },
    { text: 'Lunch with Sam' },
    { text: 'https://zomato.com/x' },
    { text: '  https://zomato.com/x  ' },
    { title: 'Order', text: 'https://zomato.com/x' },
    { text: 'https://zomato.com/x extra' },
    { text: 'Rs 5000 credited', type: 'expense' },
    { text: 'Rs 10 debited', type: 'nonsense' },
    { text: 'Rs 10 credited', type: '' },
    { text: 'Rs 10 debited', type: 'income' },
    { text: 'Rs 10 debited', type: 'transfer' },
    { text: 'Rs 10 debited', type: 'Income' },
    { text: 'x'.repeat(400) },
    { text: 'a'.repeat(139) + ' bcd' },
    { text: 'a'.repeat(139) + '😀tail' },
    { title: '   ', text: '   ', url: '   ' },
    { title: null, text: null, url: null, type: null },
    { title: '\ufeffSwiggy\ufeff', text: '\u00a0Rs 40\u3000' },
    { title: 'Swiggy', text: 'Rs 40', url: 'https://www.swiggy.com/o/1' },
    { title: 'Swiggy\n', text: '\nRs 40' },
    { title: 'Salary', url: 'https://bank.example/credit?amt=Rs%20500' },
    { url: 'https://bank.example/x Rs 500' },
    { title: 'Rs 25', url: 'not a url' },
  ];
  for (const u of urls) payloads.push({ url: u }, { text: u });
  for (const p of payloads) {
    out.push(gc('parseSharePayload', [p], parseSharePayload(p)));
  }
  return out;
}
